return {
    property: "DisplayName", // Default column to search
    operation: "contains", // Default operator
    label: "Name" // Human readable label for the placeholder
}

const displayColumnNames = [
    "Id",
    "Name",
    "Frequency",
    "Active"
];

const displayColumnOptions = {
    valueKey: {
        "Name": "DisplayName",
        "Currency": "Currency"
    },
    type: {
        "Active": "boolean",
        "PaidInArrears": "boolean"
    }
};

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
};

return [
    // --- Identifiers ---
    {
        label: "ID",
        value: "Id",
        type: "number",
        // operators: ["eq"]
    },

    // --- Core Identity ---
    {
        label: "Display Name",
        value: "DisplayName",
        type: "string",
        // operators: ["contains", "eq", "startswith"]
    },
    {
        label: "Description",
        value: "Description",
        type: "string",
        // operators: ["contains"]
    },
    {
        label: "Active",
        value: "Active",
        type: "boolean",
        operators: ["eq"] // True/False
    },

    // --- Scheduling Logic ---
    {
        label: "Frequency",
        value: "Frequency",
        type: "string",
        // operators: ["eq", "contains"]
    },
    {
        label: "Annual Pay Periods",
        value: "AnnualPayPeriods",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Paid In Arrears",
        value: "PaidInArrears",
        type: "boolean",
        operators: ["eq"]
    },

    // --- Dates ---
    {
        label: "Anchor Date",
        value: "AnchorDate",
        type: "date",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Effective From",
        value: "EffectiveFromDate",
        type: "date",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Effective To",
        value: "EffectiveToDate",
        type: "date",
        // operators: ["eq", "gt", "lt"]
    },

    // --- Relationships (Dropdowns) ---
    {
        label: "Currency",
        value: "CurrencyId",
        type: "dropdown",
        source: "currencyMap",
        operators: ["eq"]
    },
    {
        label: "Country",
        value: "CountryId",
        type: "dropdown",
        source: "countryMap",
        operators: ["eq"]
    },
    {
        label: "State",
        value: "StateId",
        type: "dropdown",
        source: "stateMap",
        operators: ["eq"]
    }

    // --- Complex Scheduling Fields (Excluded/Commented) ---
    // Fields like MonthFirstStartDay, WeekStartDayName etc. are usually 
    // too specific for high-level filtering.
    // Though, these can be added in the future.
];
